#pragma once
// Synchronous OH codec boundary. Fixture bytes come from an actual offline
// decode/encode of a synthetic frame (generated by the Python host driver).
#include <cassert>
#include <cstdint>
#include <deque>
#include <map>
#include <string>
#include <vector>
#include "record_fixtures.h"

using Bytes = std::vector<uint8_t>;
enum OH_AVErrCode { AV_ERR_OK, AV_ERR_TRY_AGAIN_LATER, AV_ERR_STREAM_CHANGED, AV_ERR_NO_MEMORY };
constexpr int HARDWARE = 1, AV_PIXEL_FORMAT_SURFACE_FORMAT = 4;
constexpr unsigned AVCODEC_BUFFER_FLAGS_EOS = 1, AVCODEC_BUFFER_FLAGS_SYNC_FRAME = 2, AVCODEC_BUFFER_FLAGS_CODEC_DATA = 8;
#define MOCK_KEY(k) constexpr const char* OH_MD_KEY_##k = #k
MOCK_KEY(WIDTH); MOCK_KEY(HEIGHT); MOCK_KEY(VIDEO_PIC_WIDTH); MOCK_KEY(VIDEO_PIC_HEIGHT);
MOCK_KEY(ENABLE_SYNC_MODE); MOCK_KEY(PIXEL_FORMAT); MOCK_KEY(FRAME_RATE); MOCK_KEY(BITRATE);
MOCK_KEY(I_FRAME_INTERVAL); MOCK_KEY(VIDEO_ENCODER_ENABLE_B_FRAME); MOCK_KEY(CODEC_CONFIG);
#undef MOCK_KEY
struct OH_AVCodecBufferAttr { int64_t pts=0; int32_t size=0,offset=0; uint32_t flags=0; };
struct OH_AVBuffer { Bytes bytes=Bytes(65536); OH_AVCodecBufferAttr attr{}; };
struct OH_AVFormat { std::map<std::string,int64_t> ints; Bytes config; };
struct OH_AVRange { int minVal,maxVal; };
struct OH_AVCapability { std::string mime; };
struct OH_AVCodec { std::string mime; OH_AVBuffer in; std::deque<OH_AVBuffer> out; };
struct OHNativeWindow { OH_AVCodec* encoder; };
namespace mock {
enum Failure { None, NoDecoder, Prepare, CorruptPts, MissingConfig, SizeChange, BadOffset, Runtime };
inline struct State {
  bool toHevc=true; Failure fail=None; int creates=0, destroys=0, configInputs=0, inputs=0, renders=0, windows=0;
  OHNativeWindow* surface=nullptr;
  const Fixture& src() const { return toHevc ? avcSource : hevcSource; }
  const Fixture& dst() const { return toHevc ? hevcTarget : avcTarget; }
} s;
inline void Emit(OH_AVCodec* c, const Bytes& bytes, int64_t pts, uint32_t flags) {
  OH_AVBuffer b; b.bytes={0xde,0xad,0xbe}; // SDK attr.offset is not always zero.
  b.attr={pts,int32_t(bytes.size()),3,flags}; b.bytes.insert(b.bytes.end(),bytes.begin(),bytes.end());
  c->out.push_back(std::move(b));
}
}
inline OH_AVCapability* OH_AVCodec_GetCapabilityByCategory(const char* mime,bool encoder,int cat) {
  assert(cat==HARDWARE); static OH_AVCapability cap;
  assert(std::string(mime)==((encoder==mock::s.toHevc)?"video/hevc":"video/avc"));cap.mime=mime;return &cap;
}
inline bool OH_AVCapability_IsHardware(OH_AVCapability*) {return true;}
inline const char* OH_AVCapability_GetName(OH_AVCapability* c) {return c->mime.c_str();}
inline bool OH_AVCapability_IsVideoSizeSupported(OH_AVCapability*,int w,int h) {return w==64 && h==64;}
inline OH_AVErrCode OH_AVCapability_GetEncoderBitrateRange(OH_AVCapability*,OH_AVRange* r) {*r={200000,8000000};return AV_ERR_OK;}
inline OH_AVCodec* OH_VideoEncoder_CreateByName(const char* n){++mock::s.creates; return new OH_AVCodec{n,{}, {}};}
inline OH_AVCodec* OH_VideoDecoder_CreateByName(const char* n){return mock::s.fail==mock::NoDecoder?nullptr:OH_VideoEncoder_CreateByName(n);}
inline OH_AVFormat* OH_AVFormat_Create(){return new OH_AVFormat;}
inline void OH_AVFormat_Destroy(OH_AVFormat* f){delete f;}
inline bool OH_AVFormat_SetIntValue(OH_AVFormat* f,const char* k,int v){f->ints[k]=v;return true;}
inline bool OH_AVFormat_SetLongValue(OH_AVFormat* f,const char* k,int64_t v){f->ints[k]=v;return true;}
inline bool OH_AVFormat_SetDoubleValue(OH_AVFormat* f,const char* k,double v){f->ints[k]=int64_t(v);return true;}
inline bool OH_AVFormat_SetBuffer(OH_AVFormat* f,const char*,const uint8_t* p,size_t n){f->config.assign(p,p+n);return true;}
inline bool OH_AVFormat_GetIntValue(OH_AVFormat* f,const char* k,int* v){*v=int(f->ints.at(k));return true;}
inline OH_AVErrCode OH_VideoEncoder_Configure(OH_AVCodec*,OH_AVFormat* f){
  assert(f->ints["WIDTH"]==64 && f->ints["HEIGHT"]==64 && f->ints["ENABLE_SYNC_MODE"]==1);
  assert(f->ints["PIXEL_FORMAT"]==4 && f->ints["BITRATE"]==500000 && f->ints["I_FRAME_INTERVAL"]==2000);
  assert(f->ints["FRAME_RATE"]==30 && f->ints["VIDEO_ENCODER_ENABLE_B_FRAME"]==0);return AV_ERR_OK;
}
inline OH_AVErrCode OH_VideoDecoder_Configure(OH_AVCodec*,OH_AVFormat* f){assert(f->config==mock::s.src().config);return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoEncoder_GetSurface(OH_AVCodec* c,OHNativeWindow** w){*w=new OHNativeWindow{c};++mock::s.windows;return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoDecoder_SetSurface(OH_AVCodec*,OHNativeWindow* w){mock::s.surface=w;return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoEncoder_Prepare(OH_AVCodec*){return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoDecoder_Prepare(OH_AVCodec*){return mock::s.fail==mock::Prepare?AV_ERR_NO_MEMORY:AV_ERR_OK;}
inline OH_AVErrCode OH_VideoEncoder_Start(OH_AVCodec*){return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoDecoder_Start(OH_AVCodec*){return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoEncoder_Stop(OH_AVCodec*){return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoDecoder_Stop(OH_AVCodec*){return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoEncoder_Destroy(OH_AVCodec* c){delete c;++mock::s.destroys;return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoDecoder_Destroy(OH_AVCodec* c){return OH_VideoEncoder_Destroy(c);}
inline void OH_NativeWindow_DestroyNativeWindow(OHNativeWindow* w){delete w;--mock::s.windows;}
inline OH_AVErrCode OH_AVBuffer_SetBufferAttr(OH_AVBuffer* b,OH_AVCodecBufferAttr* a){b->attr=*a;return AV_ERR_OK;}
inline OH_AVErrCode OH_AVBuffer_GetBufferAttr(OH_AVBuffer* b,OH_AVCodecBufferAttr* a){*a=b->attr;return AV_ERR_OK;}
inline uint8_t* OH_AVBuffer_GetAddr(OH_AVBuffer* b){return b->bytes.data();}
inline int OH_AVBuffer_GetCapacity(OH_AVBuffer* b){return int(b->bytes.size());}
inline OH_AVErrCode OH_VideoDecoder_QueryInputBuffer(OH_AVCodec*,uint32_t* idx,int64_t){*idx=0;return AV_ERR_OK;}
inline OH_AVBuffer* OH_VideoDecoder_GetInputBuffer(OH_AVCodec* c,uint32_t){return &c->in;}
inline OH_AVErrCode OH_VideoDecoder_PushInputBuffer(OH_AVCodec* c,uint32_t){
  auto a=c->in.attr;Bytes b(c->in.bytes.begin(),c->in.bytes.begin()+a.size);
  if(a.flags & AVCODEC_BUFFER_FLAGS_CODEC_DATA){assert(b==mock::s.src().config && !mock::s.configInputs++);}
  else if(a.flags & AVCODEC_BUFFER_FLAGS_EOS) mock::Emit(c,{},0,a.flags);
  else {assert(mock::s.configInputs==1 && b==mock::s.src().idr); ++mock::s.inputs; mock::Emit(c,{},a.pts,0);}
  return AV_ERR_OK;
}
inline OH_AVErrCode OH_VideoDecoder_QueryOutputBuffer(OH_AVCodec* c,uint32_t* i,int64_t){*i=0;return c->out.empty()?AV_ERR_TRY_AGAIN_LATER:AV_ERR_OK;}
inline OH_AVFormat* OH_VideoDecoder_GetOutputDescription(OH_AVCodec*){
  auto* f=new OH_AVFormat;f->ints={{"VIDEO_PIC_WIDTH",mock::s.fail==mock::SizeChange?65:64},{"VIDEO_PIC_HEIGHT",64}};return f;
}
inline OH_AVBuffer* OH_VideoDecoder_GetOutputBuffer(OH_AVCodec* c,uint32_t){return &c->out.front();}
inline OH_AVErrCode OH_VideoDecoder_FreeOutputBuffer(OH_AVCodec* c,uint32_t){c->out.pop_front();return AV_ERR_OK;}
inline OH_AVErrCode OH_VideoDecoder_RenderOutputBufferAtTime(OH_AVCodec* c,uint32_t,int64_t ns){
  auto& s=mock::s;auto pts=c->out.front().attr.pts;assert(ns==pts*1000);c->out.pop_front();
  auto* enc=s.surface->encoder;auto& d=s.dst();assert(c!=enc);
  if (++s.renders==1) {
    if(s.fail!=mock::MissingConfig) mock::Emit(enc,d.config,0,AVCODEC_BUFFER_FLAGS_CODEC_DATA);
    mock::Emit(enc,d.delta,pts,0); // output gate must independently reject this picture
  } else {
    mock::Emit(enc,d.idr,pts+(s.fail==mock::CorruptPts),AVCODEC_BUFFER_FLAGS_SYNC_FRAME);
    if(s.fail==mock::BadOffset)enc->out.back().attr.offset=INT32_MAX;
    if(s.fail==mock::Runtime)return AV_ERR_NO_MEMORY;
  }
  return AV_ERR_OK;
}
inline OH_AVErrCode OH_VideoEncoder_QueryOutputBuffer(OH_AVCodec* c,uint32_t* i,int64_t n){return OH_VideoDecoder_QueryOutputBuffer(c,i,n);}
inline OH_AVBuffer* OH_VideoEncoder_GetOutputBuffer(OH_AVCodec* c,uint32_t i){return OH_VideoDecoder_GetOutputBuffer(c,i);}
inline OH_AVErrCode OH_VideoEncoder_FreeOutputBuffer(OH_AVCodec* c,uint32_t i){return OH_VideoDecoder_FreeOutputBuffer(c,i);}
inline OH_AVErrCode OH_VideoEncoder_NotifyEndOfStream(OH_AVCodec* c){mock::Emit(c,{},0,AVCODEC_BUFFER_FLAGS_EOS);return AV_ERR_OK;}
